def draw_bars(pairs, width):
    biggest = 0
    for name, value in pairs:
        if value > biggest:
            biggest = value
    for name, value in pairs:
        ticks = int(width * value / biggest)
        print("%s | %s %d" % (name, "#" * ticks, value))

hours = {"09": 6, "10": 4, "11": 1}
pairs = []
for hour in sorted(hours):
    pairs.append(("hour " + hour, hours[hour]))
draw_bars(pairs, 10)

